def solve(data):
    enabled = set(data['defaults'])
    for layer in data['layers']:
        if layer['state'] == 'active':
            additions = set(layer['enable']).difference(layer['disable'])
            enabled.update(additions)
    return sorted(enabled)

def solve(data):
    revisions = {row['id']: row for row in data['revisions']}
    current = data['head']
    while current is not None:
        row = revisions[current]
        if row['state'] == 'issued':
            return {'id': current}
        if row['state'] == 'voided':
            break
        current = row['supersedes']
    return {'id': None}

def solve(data):
    pieces = []
    citations = []
    offset = 0
    for selection in data['ranges']:
        paragraph = selection['paragraph']
        start, end = selection['start'], selection['end']
        if selection['state'] != 'selected' or start == end:
            continue
        piece = data['paragraphs'][paragraph][start:end]
        for citation in data['citations']:
            if citation['paragraph'] != paragraph:
                continue
            left = max(start, citation['start'])
            right = min(end, citation['end'])
            if left < right:
                citations.append({'id': citation['id'], 'start': offset + left - start, 'end': offset + right - start})
        pieces.append(piece)
        offset += len(piece)
    return {'text': '\n'.join(pieces), 'citations': citations}

def solve(data):
    w, h = data['width'], data['height']
    angle = data['rotation']
    dw, dh = (h, w) if angle in (90, 270) else (w, h)
    result = []
    for x, y in data['points']:
        if not (0 <= x < dw and 0 <= y < dh):
            result.append(None)
        elif angle == 90:
            result.append([w - 1 - y, x])
        elif angle == 180:
            result.append([w - 1 - x, h - 1 - y])
        elif angle == 270:
            result.append([w - 1 - y, x])
        else:
            result.append([x, y])
    return result
